-- rowstile 0.1.0-dev: customers_see_agents. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- - type user: can view = self or workspace.work or (org.member and workspace.member) or workspace.connected
-- + type user: can view = self or workspace.work or (org.member and workspace.member) or (workspace.member and {kind = 'agent'}) or workspace.connected

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '7ce75c6b1593a2ba', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '7ce75c6b1593a2ba' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '7ce75c6b1593a2ba' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '7ce75c6b1593a2ba' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '447219fa3ac2c489' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '447219fa3ac2c489', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- views that change stay where they are, emptied (the same columns, reading nothing) while what they
-- read is dropped and made again; they are defined again below. What the app built on one stays
DO $authz_stub$
DECLARE v text; cols text;
BEGIN
  FOREACH v IN ARRAY ARRAY['"hd"."users_visible"', 'authz_int."user__view"'] LOOP
    CONTINUE WHEN pg_catalog.to_regclass(v) IS NULL;
    SELECT (SELECT string_agg(format('NULL::%s%s AS %I', pg_catalog.format_type(a.atttypid, a.atttypmod),
        CASE WHEN a.attcollation <> 0 AND a.attcollation <> t.typcollation
             THEN format(' COLLATE %I.%I', cn.nspname, co.collname) ELSE '' END, a.attname), ', ' ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
      LEFT JOIN pg_catalog.pg_collation co ON co.oid = a.attcollation
      LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid = co.collnamespace
      WHERE a.attrelid = pg_catalog.to_regclass(v) AND a.attnum > 0 AND NOT a.attisdropped) INTO cols;
    EXECUTE format('CREATE OR REPLACE VIEW %s AS SELECT %s WHERE false', v, cols);
  END LOOP;
END $authz_stub$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP POLICY IF EXISTS "authz_select" ON "hd"."users";

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'hd_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE OR REPLACE FUNCTION authz_int."team__parent__tree_compute"(p_ids uuid[]) RETURNS TABLE (o_descendant uuid, o_ancestor uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "hd"."teams" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "hd"."teams" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "hd"."teams" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "hd"."teams" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;
-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."team__parent__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 60', d.fn;
  END LOOP;
END $imm$;

-- user.view (line 40): self or workspace.work or (org.member and workspace.member) or (workspace.member and {kind = 'agent'}) or workspace.connected
CREATE OR REPLACE VIEW authz_int."user__view" AS
  SELECT x.id FROM (
  (SELECT id FROM authz_int."user__self")
  UNION ALL
  (SELECT id FROM authz_int."user__workspace__work")
  UNION ALL
  (SELECT r."id" AS id FROM "hd"."users" r
  WHERE r."id" IN (SELECT id FROM authz_int."user__org__member")
    AND r."id" IN (SELECT id FROM authz_int."user__workspace__member"))
  UNION ALL
  (SELECT r."id" AS id FROM "hd"."users" r
  WHERE r."id" IN (SELECT id FROM authz_int."user__workspace__member")
    AND coalesce((kind = 'agent'), false))
  UNION ALL
  (SELECT id FROM authz_int."user__workspace__connected")) x
  WHERE EXISTS (SELECT 1 FROM "hd"."users" w WHERE w."id" = x.id AND coalesce((active), false));

-- hd.users: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE OR REPLACE FUNCTION authz_int."hd.users:seen"(p_id uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = p_id)
      OR EXISTS (SELECT 1 FROM "hd"."users" "users" WHERE "users"."id" = p_id
        AND (SELECT authz_int.scope_cmd('hd.users', 'select')) AND ((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "users"."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false)));
END $f$;

-- hd.users select (line 120): view
CREATE POLICY "authz_select" ON "hd"."users" FOR SELECT TO "hd_app"
  USING (((SELECT authz_int.scope_cmd('hd.users', 'select')) AND ((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "users"."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false))));
COMMENT ON POLICY "authz_select" ON "hd"."users" IS 'rowstile';

-- hd.users_visible: the rows of hd.users the user may select (line 120: view)
-- mask notes (line 128): see_notes
-- @object view "hd"."users_visible"
DO $mv$
DECLARE cols text; uses text;
BEGIN
  SELECT string_agg(CASE a.attname
      WHEN 'notes' THEN format('CASE WHEN %s THEN %I.%I END AS %I', '(EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    AND coalesce((active), false))', 'users', a.attname, a.attname)
      ELSE format('%I.%I', 'users', a.attname) END, ', ' ORDER BY a.attnum) INTO cols
  FROM pg_attribute a WHERE a.attrelid = '"hd"."users"'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  -- in place when it is there: what the app built on it (a view over it) goes on working
  BEGIN
    EXECUTE format('CREATE OR REPLACE VIEW "hd"."users_visible" WITH (security_barrier) AS SELECT %s FROM "hd"."users" "users" WHERE %s',
                   cols, '(SELECT authz_int.scope_cmd(''hd.users'', ''select'')) AND ((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "users"."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR (coalesce((kind = ''agent''), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false))');
  EXCEPTION WHEN invalid_table_definition THEN
    -- its columns are not the ones it had (the table's changed): made anew, unless something is built on it
    BEGIN
      DROP VIEW "hd"."users_visible";
    EXCEPTION WHEN dependent_objects_still_exist THEN
      GET STACKED DIAGNOSTICS uses = PG_EXCEPTION_DETAIL;
      RAISE EXCEPTION 'the masked view hd.users_visible can''t be replaced in place: the columns of hd.users changed, and something is built on the view [AZ617]'
        USING DETAIL = uses, HINT = 'drop what is built on it, apply (or run the migration) again, then make it again';
    END;
    EXECUTE format('CREATE VIEW "hd"."users_visible" WITH (security_barrier) AS SELECT %s FROM "hd"."users" "users" WHERE %s',
                   cols, '(SELECT authz_int.scope_cmd(''hd.users'', ''select'')) AND ((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "users"."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR (coalesce((kind = ''agent''), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false))');
  END;
END $mv$;
COMMENT ON VIEW "hd"."users_visible" IS 'rowstile masked view';
REVOKE ALL ON "hd"."users_visible" FROM PUBLIC;
GRANT SELECT ON "hd"."users_visible" TO "hd_app";

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_text text; v_uuid uuid;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'workspace' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")));
        WHEN 'manage_roles' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")));
        WHEN 'work_all' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")))));
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'impersonate' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'see_notes' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'org_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND (((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'integration' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = v_uuid AND (((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'customer_org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'see_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = v_uuid AND ((coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'oversee' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'leadership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."leadership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."leadership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'support_grant' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."support_grant__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."support_grant__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'ticket' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'reply' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'break_glass' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__support" v WHERE v.id = o."workspace_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'comment' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."comments" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = o."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = o."ticket_id")))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'workspace.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.manage_roles' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.work_all' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.work' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.impersonate' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.see_notes' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.org_tickets' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'integration.manage_keys' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'integration.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE ((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE ((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE o."id" > p_after::uuid AND ((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'customer_org.see_tickets' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE (coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE (coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE o."id" > p_after::uuid AND (coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'customer_org.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'customer_org.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'team.oversee' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."parent_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."parent_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."parent_id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'team.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."parent_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."parent_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."parent_id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'team.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."teams" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'ticket.work' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'ticket.reply' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
