    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'ticket.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."team__oversee" v WHERE v.id = o."team_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'ticket.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'ticket.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'ticket.break_glass' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__support" v WHERE v.id = o."workspace_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__support" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."tickets" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__support" v WHERE v.id = o."workspace_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'comment.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."comments" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = o."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = o."ticket_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."comments" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = o."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = o."ticket_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."comments" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = o."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = o."ticket_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."user__view__who"(p_id uuid) RETURNS SETOF uuid
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."user__self__who"(p_id) x)
  UNION ALL
  (SELECT x FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg, LATERAL authz_int."workspace__work__who"(tg.id) x)
  UNION ALL
  ((SELECT x FROM (SELECT r."customer_org_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."customer_org_id" IS NOT NULL) tg, LATERAL authz_int."customer_org__member__who"(tg.id) x) INTERSECT (SELECT x FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg, LATERAL authz_int."workspace__member__who"(tg.id) x))
  UNION ALL
  (SELECT x FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg, LATERAL authz_int."workspace__member__who"(tg.id) x)
  UNION ALL
  (SELECT x FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg, LATERAL authz_int."workspace__connected__who"(tg.id) x)
$f$;

CREATE OR REPLACE FUNCTION authz_int."user__view__why"(p_id uuid, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."user__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM "hd"."users" w WHERE w."id" = p_id AND coalesce((active), false)) THEN
    RETURN NEXT pad || 'no   user ' || p_id || ' fails the type''s where {' || 'active' || '}';
    RETURN;
  END IF;
  RETURN NEXT pad || 'user.view = self or workspace.work or (org.member and workspace.member) or (workspace.member and {kind = ''agent''}) or workspace.connected';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__self");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'self';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."user__self__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__workspace__work");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.work';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('workspace', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has work' ELSE ', without work' END;
      IF NOT ('workspace:work:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."workspace__work__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('workspace:work:' || v_t.id));
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."users" r
  WHERE r."id" IN (SELECT id FROM authz_int."user__org__member")
    AND r."id" IN (SELECT id FROM authz_int."user__workspace__member"));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(org.member and workspace.member)';
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__org__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'org.member';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."customer_org_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."customer_org_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('customer_org', v_t.id) THEN
        RETURN NEXT pad || '  ' || '       ' || 'org is a customer_org you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'org is customer_org '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has member' ELSE ', without member' END;
      IF NOT ('customer_org:member:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."customer_org__member__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('customer_org:member:' || v_t.id));
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__workspace__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.member';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('workspace', v_t.id) THEN
        RETURN NEXT pad || '  ' || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has member' ELSE ', without member' END;
      IF NOT ('workspace:member:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."workspace__member__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('workspace:member:' || v_t.id));
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."users" r
  WHERE r."id" IN (SELECT id FROM authz_int."user__workspace__member")
    AND coalesce((kind = 'agent'), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(workspace.member and {kind = ''agent''})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__workspace__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.member';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('workspace', v_t.id) THEN
        RETURN NEXT pad || '  ' || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has member' ELSE ', without member' END;
      IF NOT ('workspace:member:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."workspace__member__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('workspace:member:' || v_t.id));
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."users" r WHERE coalesce((kind = 'agent'), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{kind = ''agent''}';
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__workspace__connected");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.connected';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('workspace', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has connected' ELSE ', without connected' END;
      IF NOT ('workspace:connected:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."workspace__connected__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('workspace:connected:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'workspace' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" "workspaces" WHERE "workspaces"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('hd.workspaces', 'select')) AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "workspaces"."id"));
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."users" "users" WHERE "users"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('hd.users', 'select')) AND ((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "users"."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false)));
    WHEN 'integration' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."integrations" "integrations" WHERE "integrations"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('hd.integrations', 'select')) AND ((coalesce("integrations"."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "integrations"."workspace_id"))
    AND coalesce((active), false)));
    WHEN 'customer_org' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" "customer_orgs" WHERE "customer_orgs"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('hd.customer_orgs', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "customer_orgs"."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "customer_orgs"."workspace_id")));
    WHEN 'team' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."teams" "teams" WHERE "teams"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('hd.teams', 'select')) AND EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "teams"."workspace_id"));
    WHEN 'membership' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."team_members" "team_members" WHERE ("team_members"."team_id", "team_members"."user_id") = (((p_id)::authz_gen."membership__key")."team_id", ((p_id)::authz_gen."membership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('hd.team_members', 'select')) AND EXISTS (SELECT 1 FROM authz_int."team__view" v WHERE v.id = "team_members"."team_id"));
    WHEN 'leadership' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."team_leads" "team_leads" WHERE ("team_leads"."team_id", "team_leads"."user_id") = (((p_id)::authz_gen."leadership__key")."team_id", ((p_id)::authz_gen."leadership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('hd.team_leads', 'select')) AND EXISTS (SELECT 1 FROM authz_int."team__view" v WHERE v.id = "team_leads"."team_id"));
    WHEN 'support_grant' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."support_access" "support_access" WHERE ("support_access"."workspace_id", "support_access"."staff_id") = (((p_id)::authz_gen."support_grant__key")."workspace_id", ((p_id)::authz_gen."support_grant__key")."staff_id")
        AND (SELECT authz_int.scope_cmd('hd.support_access', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "support_access"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."user__self" v WHERE v.id = "support_access"."staff_id")));
    WHEN 'ticket' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."tickets" "tickets" WHERE "tickets"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('hd.tickets', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = "tickets"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = "tickets"."id")
    OR ((coalesce("tickets"."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = "tickets"."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "tickets"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = "tickets"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = "tickets"."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "tickets"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "tickets"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = "tickets"."workspace_id")
    AND (coalesce("tickets"."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = "tickets"."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = "tickets"."id")
    OR authz_int."team__oversee__has"("tickets"."team_id")))));
    WHEN 'comment' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."comments" "comments" WHERE "comments"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('hd.comments', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = "comments"."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = "comments"."ticket_id"))));
    ELSE RETURN false;
  END CASE;
END $f$;

