hd.team_members:update:refuse"', '"hd.team_members:update:why"', '"hd.teams:column id, workspace_id:items"', '"hd.teams:column id, workspace_id:why"', '"hd.teams:column parent_id after:items"', '"hd.teams:column parent_id after:why"', '"hd.teams:delete:items"', '"hd.teams:delete:why"', '"hd.teams:insert:items"', '"hd.teams:insert:refuse"', '"hd.teams:insert:why"', '"hd.teams:rules:explain"', '"hd.teams:update:items"', '"hd.teams:update:refuse"', '"hd.teams:update:why"', '"hd.tickets:column id, workspace_id, requester_id:items"', '"hd.tickets:column id, workspace_id, requester_id:why"', '"hd.tickets:column status after:items"', '"hd.tickets:column status after:why"', '"hd.tickets:column status:items"', '"hd.tickets:column status:why"', '"hd.tickets:column subject:items"', '"hd.tickets:column subject:why"', '"hd.tickets:column team_id after:items"', '"hd.tickets:column team_id after:why"', '"hd.tickets:column team_id, assignee_id:items"', '"hd.tickets:column team_id, assignee_id:why"', '"hd.tickets:delete:items"', '"hd.tickets:delete:why"', '"hd.tickets:insert:items"', '"hd.tickets:insert:refuse"', '"hd.tickets:insert:why"', '"hd.tickets:rules:explain"', '"hd.tickets:update:items"', '"hd.tickets:update:refuse"', '"hd.tickets:update:why"', '"hd.tickets:update_after:items"', '"hd.tickets:update_after:refuse"', '"hd.tickets:update_after:why"', '"hd.users:column customer_org_id after:items"', '"hd.users:column customer_org_id after:why"', '"hd.users:column customer_org_id:items"', '"hd.users:column customer_org_id:why"', '"hd.users:column id, workspace_id, kind:items"', '"hd.users:column id, workspace_id, kind:why"', '"hd.users:column notes:items"', '"hd.users:column notes:why"', '"hd.users:column role, active:items"', '"hd.users:column role, active:why"', '"hd.users:insert:items"', '"hd.users:insert:refuse"', '"hd.users:insert:why"', '"hd.users:rules:explain"', '"hd.users:update:items"', '"hd.users:update:refuse"', '"hd.users:update:why"', '"hd.workspaces:column id:items"', '"hd.workspaces:column id:why"', '"hd.workspaces:rules:explain"', '"hd.workspaces:update:items"', '"hd.workspaces:update:refuse"', '"hd.workspaces:update:why"']::text[]) LOOP
